import React, { useEffect, useRef, useState } from 'react';
import {
  GoogleMap,
  Marker,
  Polyline,
  Circle,
  InfoWindow,
  useLoadScript,
} from '@react-google-maps/api';

import { buses, routes, stations } from '../api';

/* ================= MAP CONFIG ================= */

const LAHORE_CENTER = { lat: 31.5204, lng: 74.3587 };

const MAP_BOUNDS = {
  north: 31.65,
  south: 31.35,
  west: 74.15,
  east: 74.55,
};

const BUS_ICONS = {
  MOVING: 'https://maps.google.com/mapfiles/ms/icons/blue-dot.png',
  BROKEN: 'https://maps.google.com/mapfiles/ms/icons/red-dot.png',
  OFFLINE: 'https://maps.google.com/mapfiles/ms/icons/grey-dot.png',
};

/* ================= COMPONENT ================= */

const LiveMap = () => {
  const { isLoaded } = useLoadScript({
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY,
  });

  const mapRef = useRef(null);

  const [routeList, setRouteList] = useState([]);
  const [routePaths, setRoutePaths] = useState({});
  const [stationList, setStationList] = useState([]);
  const [busLocations, setBusLocations] = useState([]);
  const [selectedBus, setSelectedBus] = useState(null);
  const [loading, setLoading] = useState(true);

  /* ================= FETCH DATA ================= */

  useEffect(() => {
    fetchInitialData();
    const interval = setInterval(fetchLiveBuses, 5000);
    return () => clearInterval(interval);
  }, []);

  const fetchInitialData = async () => {
    await Promise.all([fetchRoutes(), fetchStations(), fetchLiveBuses()]);
    setLoading(false);
  };

  const fetchRoutes = async () => {
    const res = await routes.getAll();
    setRouteList(res.data);

    res.data.forEach(async (route) => {
      const pathRes = await routes.getPath(route.route_id);
      setRoutePaths((prev) => ({
        ...prev,
        [route.route_id]: pathRes.data.map((p) => ({
          lat: Number(p.latitude),
          lng: Number(p.longitude),
        })),
      }));
    });
  };

  const fetchStations = async () => {
    const res = await stations.getAll();
    setStationList(
      res.data.map((s) => ({
        ...s,
        lat: Number(s.latitude),
        lng: Number(s.longitude),
      }))
    );
  };

  const fetchLiveBuses = async () => {
    const res = await buses.getLocations();
    setBusLocations(
      res.data.map((b) => ({
        ...b,
        latitude: Number(b.latitude),
        longitude: Number(b.longitude),
        last_updated: new Date(b.last_updated),
      }))
    );
  };

  /* ================= HELPERS ================= */

  const getRouteColor = (status) => {
    if (status === 'COMPLETED') return '#2563eb';
    if (status === 'ISSUE') return '#f97316';
    return '#16a34a';
  };

  const getBusState = (bus) => {
    const diff = Date.now() - bus.last_updated.getTime();
    if (diff > 15000) return 'OFFLINE';
    return bus.bus_status || 'MOVING';
  };

  if (!isLoaded) return <div>Loading Lahore Map…</div>;

  /* ================= RENDER ================= */

  return (
    <GoogleMap
      center={LAHORE_CENTER}
      zoom={12}
      mapContainerStyle={{ width: '100%', height: '100vh' }}
      options={{
        restriction: { latLngBounds: MAP_BOUNDS },
        streetViewControl: false,
      }}
      onLoad={(map) => (mapRef.current = map)}
    >
      {/* ROUTE POLYLINES */}
      {routeList.map((route) => (
        <Polyline
          key={route.route_id}
          path={routePaths[route.route_id]}
          options={{
            strokeColor: getRouteColor(route.status),
            strokeWeight: 6,
          }}
        />
      ))}

      {/* STATIONS (CIRCLES) */}
      {stationList.map((s) => (
        <Circle
          key={s.station_id}
          center={{ lat: s.lat, lng: s.lng }}
          radius={60}
          options={{
            fillColor: '#ffffff',
            fillOpacity: 1,
            strokeColor: '#000000',
            strokeWeight: 1,
          }}
        />
      ))}

      {/* LIVE BUSES */}
      {busLocations.map((bus) => {
        const state = getBusState(bus);

        return (
          <Marker
            key={bus.bus_id}
            position={{
              lat: bus.latitude,
              lng: bus.longitude,
            }}
            icon={BUS_ICONS[state]}
            onClick={() => setSelectedBus(bus)}
          />
        );
      })}

      {/* BUS INFO WINDOW */}
      {selectedBus && (
        <InfoWindow
          position={{
            lat: selectedBus.latitude,
            lng: selectedBus.longitude,
          }}
          onCloseClick={() => setSelectedBus(null)}
        >
          <div>
            <strong>Bus #{selectedBus.bus_id}</strong>
            <br />
            Route: {selectedBus.route_id}
            <br />
            Status: {getBusState(selectedBus)}
          </div>
        </InfoWindow>
      )}

      {loading && <div>Loading data…</div>}
    </GoogleMap>
  );
};

export default LiveMap;
